import java.util.Scanner;
public class JStars1
{
	public static void main (String[] args)
	{		
		//Khutwa 1: Qra adad al-sufuuf fi namat muthallal al-nujoom al-qaem
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil adad al-sufuuf fi namat muthallal al-nujoom al-qaem: ");
		int N = scan.nextInt();
		scan.close();
		//Khutwa 2: Tba'a as-sufuuf fi namat al-nujoom wahda bi wahda
		for (int i = 1; i <= N; i++)
		{
			//Khutwa 2.1: Tba'a al-asterisks fi s-saff al-raqam i
			for (int j = 1; j <= i; j++) {
				System.out.print("*");
			}
			System.out.println();
		}
	}
}
